#include <stdio.h>

int main(void) {
    for (int i = 1; i <= 5; i++) {
        printf("Bus stop %d\n", i);
    }

    int sum = 0;
    for (int n = 1; n <= 10; n++) {
        sum = sum + n;
    }
    printf("Sum of 1 to 10 = %d\n", sum);

    for (int t = 3; t >= 1; t--) {
        printf("%d... ", t);
    }
    printf("Go!\n");
    return 0;
}

